CREATE PROCEDURE Sp_UnitWiseJobOrderBal_Reg_Custom  (@Coycode as int, @OrdId as nvarchar(1000),@PId as nvarchar(1000),@OrderType varchar(15),@OrdStatus as int,@StyleNo as NVarchar(4000),@IpAddress nvarchar(1000))  AS  BEGIN  DECLARE @SQLSTR AS NVARCHAR(4000) Set @SQLSTR =N'select OrderMAs.jobno as OrdNo,ORdermas.finyear as ORdFinyear,OrderMAs.buyordNo,X.styleno,Mas_fabric.Fabdesc ,ColorDesc, x.gsm,fingsm, 0 as ReqKgs, sum(Jobkgs-RetKgs) JobOrderKgs ,sum(consKgs) ConsKgs,sum(JobKgs-RetKgs-conskgs) as BalKgs,sum(RetnLot) as RetLotKgs, avg(Pcswt) as P_Pcswt ,avg(CutQty) as cutQty,empid from (  select ordid,styleno,fabid ,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm,0 as Jobkgs,0 as Reqkgs,0 as RetKgs ,sum(Reqkgs) as Conskgs,0 as RetnLot,Diaid as PrgKnitDiaId,empid from  Pro_ReqJob_1 	group by ordid,styleno, fabid ,colid,cntid,gsm,gg,ll,Diaid,findiaid, fingsm,empid UNION select trs_del2.Ordid,trs_del2.styleno ,fabid,colid,cntid,gsm,gg,ll,diaid,findiaid,fingsm ,0 as Reqkgs,sum(trs_del2.Kg) as JobKgs,0 as RetKgs,0 as Conskgs,0 as RetnLot,PrgKnitDiaId,isnull(Empid,0) as Empid from  TRs_del1 inner join trs_del2 on trs_del1.id =trs_del2.id inner join stocktable on trs_del2.stockid=stocktable.stockid where trs_del1.trtype=-2 and DEltype=''P'' group by trs_del2.ordid,trs_del2.styleno,fabid,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm,PrgKnitDiaId,isnull(Empid,0) UNION select trs_grn2.Ordid,trs_grn2.styleno , fabid,colid,cntid,gsm,gg,ll,diaid,findiaid,fingsm,0 as Reqkgs ,0 as JobKgs,sum(trs_grn2.RecKgs) as RetKgs ,0 as Conskgs,0 as RetnLot,PrgKnitDiaId,0 as empid from  trs_grn1 inner join trs_grn2 on trs_grn1.id =trs_grn2.id inner join stocktable on trs_grn2.stockid=stocktable.stockid where trs_grn1.Grntype=''FabricRetToUnit'' group by trs_grn2.ordid,trs_grn2.styleno,fabid,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm,PrgKnitDiaId UNION Select trs_del2.Ordid,trs_del2.styleno ,fabid,colid,cntid,gsm,gg,ll,diaid,findiaid,fingsm ,0 as Reqkgs,0 as JobKgs,0 as RetKgs,0 as Conskgs,sum(trs_del2.Kg) as RetnLot,PrgKnitDiaId,isnull(Empid,0) as Empid from  TRs_del1 inner join trs_del2 on trs_del1.id = trs_del2.id inner join stocktable on trs_del2.stockid=stocktable.stockid where trs_del1.trtype=-2 and DEltype=''R'' group by trs_del2.ordid,trs_del2.styleno,fabid,colid,cntid,gsm,gg,ll,Diaid,findiaid,fingsm,PrgKnitDiaId ,isnull(Empid,0) )X INNER JOIN  OrderMas (nolock) on x.ordid=ordermas.ordid  LEFT JOIN  (Select Ordid, FabDesc,FabClr,avg(pcswgt) as PcsWt from  Prog_ClrComb A INNER JOIN Prog_Cns B ON A.ID = B.ID  group by Ordid,FabDesc,FabClr) X1 ON x.Ordid = X1.Ordid and X.FabID  = X1.FabDesc and X.ColId = X1.FabClr LEFT JOIN (Select Ordid,isnull(Sum(isnull(Q1,0) + isnull(Q2,0)+isnull(Q3,0) +isnull(Q4,0) + isnull(Q5,0) + isnull(Q6,0) +isnull(Q7,0) + isnull(Q8,0) + isnull(Q9,0) + isnull(Q10,0) + isnull(Q11,0) + isnull(Q12,0)  +isnull(Q13,0) + isnull(Q14,0) + isnull(Q15,0)),0) as CutQty from Temp_Dtl Where Operation = ''Cut.Qty'' and IpAddress = @IpAddress Group by OrdID) T ON X.Ordid =  T.Ordid  LEFT OUTER JOIN Mas_fabric(nolock) on x.fabid=MAs_fabric.fabid LEFT OUTER JOIN  Mas_color (nolock) on  x.colid =MAs_color.ColID LEFT OUTER JOIN  Mas_count (nolock) on x.CntID =MAs_count.CountID  LEFT OUTER JOIN  Mas_dia KDia (nolock)  on x.Diaid=KDia.Diaid left outer join MAs_Dia FDia (nolock) on  x.Diaid=FDia.Diaid  LEFT OUTER JOIN  Mas_Dia PrgKDia (nolock)  on  x.PrgKnitDiaId=PrgKDia.Diaid LEFT OUTER JOIN  Mas_Exporter on ordermas.expid= MAs_exporter.expid where Ordertype in (select IDStr from fnSplitter_Str(@OrderType))' if @OrdStatus <>2begin set @SQLSTR=@SQLSTR+N' and Completed=@OrdStatus ' end If Len(Rtrim(@StyleNo))>0 Begin Set @SQLSTR=@SQLSTR+N' AND x.StyleNo in (Select IDStr From fnSplitter_Str(@StyleNO))' End  if len(RTRIM(@OrdId))>0  begin  Set @SQLSTR=@SQLSTR+N' AND x.OrdId in (Select ID From fnSplitter(@OrdId))' end  Set @SQLSTR=@SQLSTR+N' group by ordermas.expid, OrderMAs.jobno, ORdermas.finyear, OrderMAs.buyordNo, X.styleno, Mas_fabric.Fabdesc, ColorDesc, x.gsm, fingsm,Empid' Exec SP_EXECUTESQL @SQLSTR,N'@Coycode int,@OrdId nvarchar(200),@Pid nvarchar(200),@OrderType varchar(15),@OrdStatus int,@StyleNo as NVarchar(4000),@IpAddress nvarchar(1000)', @Coycode=@coycode,@OrdId=@OrdId,@Pid=@Pid,@OrderType=@OrderType, @OrdStatus=@OrdStatus ,@StyleNo=@StyleNo, @IpAddress=@IpAddress end